  | |- _ (MS _ _ (if ?c then Z_to_bv 64 0xaf32c else _) _ _ _ _) =>
      replace c with false; [cbv_concl_iota | symmetry; zchk_solve]
  | |- _ (MS _ _ (if ?c then _ else Z_to_bv 64 0xaf32c) _ _ _ _) =>
