    change (256 / 8) with 32 in SBND, APS.
    assert (APB : FB + 256 <= BUF \/ BUF + Z.of_nat (length bs) <= FB) by (apply F3; apply in_app_iff; left; exact BIN).
    pose proof (hm_aobj_block asegs R HIA h1 LB _ mm BUF _ HH1 BIN) as OBUF. rewrite Ehcs in OBUF.
    assert (BINA : In (BUF, Z.of_nat (length bs)) (LB ++ fdata ((FB, 256) :: LF))) by (apply in_app_iff; left; exact BIN).
