                 | |- lo <= _ - _ => clear - SLO SP1 NS1 NA1 NB1 STKn0; lia
                 | |- crange _ lo _ => exact SCS1
                 | |- SAN + 80 <= lo \/ _ => left; exact SANLO
                 | |- 80 = 0 \/ _ => right; clear - SANLO SLO SPH NS1 NA1 NB1 STKn0; lia
                 | |- 80 < _ => clear; lia
                 | |- client_wrange _ _ _ _ _ _ => eapply client_wrange_sp_mono; [exact LOS| exact CWS1]
                 | |- _ <= htop _ _ _ _ => clear - SP1 TOP; lia
                 end
               | match goal with |- ?g => idtac "MS-PRE-LEFT:" g end ]));
      (match goal with H : u8arr _ _ SAN _ |- _ => apply (rw_cells_of_u8arr asegs) in H; rewrite repeat_length in H; change (Z.to_nat 80) with 80%nat in H end);
      (match goal with H : ?x = Z_to_bv 64 SAN |- _ => subst x end);
      (* [comment removed for export] *)
      (try lxg_b8u; lx_pre; lxr_path; lxr_abase; lxr_pose; lx_pre; lx_run_tac (PLAN [716788] [] 80%N); lx_tree; lxr_leaf; lx_carry)
      (* [comment removed for export] *)
      .
    all: eapply tail_walk; first [ eassumption | clear; lia | match goal with |- ?g => idtac "MS-LEFT:" g end ].
  Qed.
