  Proof.
    intros until x31. intros SP1 SP1M HH1 Ehcs Ehtop Estk F64 FRSH FH FSH SAVE STK2 ST1 MI HSAN OSAN APSAN PRES SS1 SS2 RR.
    rt_facts.
    pose proof (hm_top asegs R HIA h1 LB _ _ HH1) as HTOP. rewrite Ehtop, Estk in HTOP.
    assert (SP1R : 0 <= sp1 < 2^64) by (clear - SP1 SPR SLO LOS ALO ACV NS1 NA1 NB1 STKn0; lia).
    assert (SCS : crange CS lo (bv_unsigned sp - lo)) by (eapply crange_sub; [exact SCS0| clear - LOS; lia| clear - SLO NS1 NA1 NB1 STKn0 TOP HTOP; lia]).
    assert (SCS1 : crange CS lo (sp1 - lo)) by (eapply crange_sub; [exact SCS| clear; lia| clear - SP1; lia]).
    destruct (frame_factsA R HIA CS h1 LB LF mm FB 256 lo HH1 Ehcs FRSH F64 ltac:(clear; lia) ltac:(reflexivity) LOS)
      as (CFB & INF & INH & IND & AP & (F0 & F1 & F2 & F3) & F8 & FBLO & SBND & APS).
    change (256 / 8) with 32 in SBND, APS.
    assert (APB : FB + 256 <= BUF \/ BUF + Z.of_nat (length bs) <= FB) by (apply F3; apply in_app_iff; left; exact BIN).
    pose proof (hm_aobj_block asegs R HIA h1 LB _ mm BUF _ HH1 BIN) as OBUF. rewrite Ehcs in OBUF.
    assert (BINA : In (BUF, Z.of_nat (length bs)) (LB ++ fdata ((FB, 256) :: LF))) by (apply in_app_iff; left; exact BIN).
    assert (BUFC : BUF + Z.of_nat (length bs) <= alloc_ceiling).
    { destruct (blocks_below_hm R HIA h1 LB _ mm LB HH1 ltac:(intros b Hb; exact Hb) _ BIN) as [_ BCE]. cbn [fst snd] in BCE. exact BCE. }
    assert (BUFLO : BUF + Z.of_nat (length bs) <= lo) by (clear - BUFC ALO LOS; lia).
    assert (CWS1 : client_wrange L (LB ++ fdata ((FB, 256) :: LF)) lo (htop asegs R HIA h) SAN 80)
      by (eapply client_wrange_mono; [exact CWS| intros b Hb; apply fdata_cons_sub; exact Hb]).
    assert (WL : wlow R LB LF) by (split; [exact (proj2 (proj2 (proj2 PRES)))| apply (art_data_lo asegs R HIA)]).
    assert (WCS : wcover R LB LF (bv_unsigned sp) W SAN 80) by (apply wcover_inside; cbn [inside]; left; clear; lia).
