    lazymatch goal with HS : rw_cells _ ?mx SAN [CB 80 ?zs] |- _ =>
      pose proof (rw_cells_reshape asegs mx SAN _ [C4 (Z_to_bv 64 0); CB 76 (repeat (Z_to_bv 8 0) 76)] HS
                    ltac:(cbn; repeat split; reflexivity) ltac:(first [exact eq_refl | vm_compute; reflexivity])) as HSANf; clear HS end.
    ex_exq. eexists. exists 0. repeat (lazymatch goal with |- ex _ => eexists end).
    split; [reflexivity|]. spine;
      first [ eassumption | (clear - RR; lia) | clear; lia | (cbn [cells_size csize Nat.add length]; reflexivity)
            | (let E4 := fresh "E4" in intros E4; exfalso; (clear - E4; lia))
            | match goal with |- ?g => idtac "OERR-EXQ-LEFT:" g end ].
